import{_ as p,o as r,c as e,a2 as t}from"./chunks/framework.F7eQ-ohH.js";const c=JSON.parse('{"title":"央国企面试如何做自我介绍（技术类）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/面试指南/1.央国企面试如何做自我介绍（技术类）.md","filePath":"docs/面试指南/1.央国企面试如何做自我介绍（技术类）.md","lastUpdated":1788881428000}'),x={name:"docs/面试指南/1.央国企面试如何做自我介绍（技术类）.md"};function o(n,a,s,h,i,l){return r(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="央国企面试如何做自我介绍-技术类" tabindex="-1"><strong>央国企面试如何做自我介绍（技术类）</strong> <a class="header-anchor" href="#央国企面试如何做自我介绍-技术类" aria-label="Permalink to &quot;**央国企面试如何做自我介绍（技术类）**&quot;">​</a></h1><p>自我介绍的方法几乎所有企业面试都差不多，央国企也没什么特别，最重要的是把自己的教育背景、研究经历、实习经历和能够证明你能力的东西说清楚，在此基础上如果能够突出你的稳定性和吃苦耐劳的能力的话就更好了。</p><h1 id="自我介绍应该怎么组织" tabindex="-1">自我介绍应该怎么组织？ <a class="header-anchor" href="#自我介绍应该怎么组织" aria-label="Permalink to &quot;自我介绍应该怎么组织？&quot;">​</a></h1><p>一般自我介绍按照如下几点组织即可：基本信息、科研/实习/项目经历、校园经历、技术能力、兴趣爱好。</p><p>对于时间较短的自我介绍，如果说不完上面所有内容，那么只需要说基本信息、科研&amp;实习经历、兴趣爱好即可，因为重点关注的还是学历和你解决问题的能力，所以教育背景和科研&amp;实习&amp;项目经历是你自我介绍中的重点</p><h1 id="基本信息怎么说" tabindex="-1">基本信息怎么说？ <a class="header-anchor" href="#基本信息怎么说" aria-label="Permalink to &quot;基本信息怎么说？&quot;">​</a></h1><p>基本信息简单来说包含2个分：基础信息+教育背景。</p><p>基础信息包括姓名、籍贯、毕业学校、所学专业等信息，描述清楚就可以了，至于年龄、党员之类的话，不是特别需要去提及，感兴趣的面试官会问。所以这部分可以这样说：</p><p><strong>面试官你好，我叫小明，来自于xxx省xxx市，毕业于xxx大学xxx重点实验室，所学专业是xxx。</strong></p><h1 id="科研-实习-项目经历怎么说" tabindex="-1">科研&amp;实习&amp;项目经历怎么说？ <a class="header-anchor" href="#科研-实习-项目经历怎么说" aria-label="Permalink to &quot;科研&amp;实习&amp;项目经历怎么说？&quot;">​</a></h1><p>在完成自我介绍之后，接下来就是介绍你在学校的科研、实习和项目经历了，这里需要科普一下，和各种培训私企的辅导班，喜欢让大家去做什么商城项目、外卖项目不同，你面试国企拿这些项目去面试并不算加分项。</p><p>对于应届生，我们还是更希望看到你在实验室的科研、横向等实验室项目，这些项目可能在互联网大厂哪里觉得是垃圾，但是国企面试官通常还是对这些东西比较感兴趣的。</p><h2 id="项目-实习并不是越多越好" tabindex="-1">项目&amp;实习并不是越多越好 <a class="header-anchor" href="#项目-实习并不是越多越好" aria-label="Permalink to &quot;项目&amp;实习并不是越多越好&quot;">​</a></h2><p>所以你自我介绍的第二部分可以说说你在学校做的科研项目、横向项目和实习之类的，注意这些都可以说但是不要太多。</p><p>比如说你参加了十几个科研项目、横向项目啥的不需要都说出来，而是应该挑选2～3个你觉得最好的，最有亮点的项目来说。剩下的项目则可以一笔带过，说除此之外还参与了xxx项目等xxx个项目。</p><p>下面提供的模板呢对于项目经历、科研经历、实习经历等内容都很适用，大家自行进行相应替换就可以了。</p><h2 id="项目-科研-实习经历的介绍模板-三段式方法-2个左右" tabindex="-1">项目&amp;科研&amp;实习经历的介绍模板（三段式方法，2个左右） <a class="header-anchor" href="#项目-科研-实习经历的介绍模板-三段式方法-2个左右" aria-label="Permalink to &quot;项目&amp;科研&amp;实习经历的介绍模板（三段式方法，2个左右）&quot;">​</a></h2><p><strong>（1）项目背景</strong></p><p>一定要先说说你的项目背景，最好带上学校，实验室，项目来源这些这些基础信息，让面试官对你的项目有个大概的了解。</p><p><strong>模板：</strong> 我在学校期间我主要参与了xxx项目，这个项目是xxx重点实验室 /xxx公司的横向/纵向/企业项目。这个项目呢主要是为了解决xxx问题。</p><p><strong>举个栗子（这里up瞎扯哈）：</strong> 我在学校期间呢主要参加了和xxx公司合作的自动驾驶项目，这个项目主要是xxx企业的一个商业项目然后xxx模块呢交给我们开发。主要是为了解决自动驾驶过程中人物识别的准确度不高的问题。</p><p><strong>（2）工作内容</strong></p><p>这部分呢主要突出你在项目&amp;科研&amp;实习中遇到了困难，以及这些困难是怎么解决的，因为大多数央企面试想要看到的不是你有多么丰富的履历，多么高的分数，而是看你解决问题的实际能力。</p><p>所以呢，大家在进行自我介绍的时候一定要把项目中遇到了什么问题，有什么亮点，和取得了什么成果给面试官说清楚，这样以来是让面试官看到你解决问题的能力，<strong>另一个方面呢也可以在这里埋下伏笔，诱导面试官去提问你已经准备好的问题。</strong></p><p><strong>模板：</strong> 我在项目中担任了xxx角色，负责了xxx模块，在工作过程中遇到了xxx问题，运用了xxx技术，解决了xxx问题。</p><p><strong>举个栗子（这里都是up瞎扯）</strong> ：在这个项目中呢，我主要负责的是软件开发的相关工作，具体负责了人物识别模块的开发工作。在工作过程中呢，我遇到了由于GPU算力过低导致的识别效率较低的问题，针对这个问题呢我现实查询了相关论文，采用了xxx方法进行了模型裁剪和优化。</p><p><strong>（3）项目成果</strong></p><p>项目总结是对你项目介绍的完美闭环，既然你做了这么多事情，我总得知道你取得了什么成果吧？</p><p>你不能说你是只老黄牛只知道干活儿，天天耕地没产出吧？那你这样没产出我们公司招你进来干啥？</p><p>所以，对于项目介绍完毕，一定需要输出可量化的项目成果，这个成果可以是实验数据的提升、可以是发表的sci论文，也可以是发表的专利等等。</p><p><strong>模板：</strong> 最后，通过我提出的方法，成功的将精度提升了xx%（or：成功发表了xx篇论文，发表了xx专利，如果这些都没有，写上锻炼了自己的开发能力也行）</p><p><strong>举个栗子：</strong> 最后通过我采用的xxx方法，使得人物检测模块的精度提升了10%，运行效率提升了20%，成果完成了项目交付（发表了sci论文一篇）。</p><h1 id="自我评价-兴趣爱好怎么说" tabindex="-1">自我评价&amp;兴趣爱好怎么说？ <a class="header-anchor" href="#自我评价-兴趣爱好怎么说" aria-label="Permalink to &quot;自我评价&amp;兴趣爱好怎么说？&quot;">​</a></h1><h2 id="兴趣爱好-没有可以不说" tabindex="-1">兴趣爱好（没有可以不说） <a class="header-anchor" href="#兴趣爱好-没有可以不说" aria-label="Permalink to &quot;兴趣爱好（没有可以不说）&quot;">​</a></h2><p>兴趣爱好呢其实是国企的自我介绍里面比较关注的一环，还是那句话除了学习、技术能力，国企面试官还是希望你多才多艺一点儿（PS：不然每年年会表演的尴尬节目谁来参加？）</p><p>所以呢，兴趣爱好其实是能够将你塑造成一个更立体的人物形象的，介绍的方法呢不建议大家干瘪瘪的说我喜欢打篮球、喜欢跳舞、喜欢看书和喜欢雪豹。</p><p>你可以通过一些校园经历来佐证你的兴趣爱好，例如：</p><p>我喜欢篮球，参加了学院3年的篮球比赛，获得了xxx奖。之类的，反正最好能够有实际案例来支持你的兴趣爱好。</p><h2 id="自我评价" tabindex="-1">自我评价 <a class="header-anchor" href="#自我评价" aria-label="Permalink to &quot;自我评价&quot;">​</a></h2><p>另外自我评价方面的话，一定要多说些吃苦耐劳，稳定性好的话，因为国企还是希望你来了能够多待一会儿的，别来了就走了。</p><p>如JG类央企的话，由于出差多，压力较大，加班也较多，你可以突出下自己热爱工作，不怕幸苦，甚至乐意为国防做贡献之类的都可以，能大大提升你面试成功率。</p><h2 id="建立自己的自我介绍模板-反复练习" tabindex="-1">建立自己的自我介绍模板，反复练习 <a class="header-anchor" href="#建立自己的自我介绍模板-反复练习" aria-label="Permalink to &quot;建立自己的自我介绍模板，反复练习&quot;">​</a></h2><p>最后，大家如果对于面试这块儿不自信的话，一定要建立自己的面试模板，反复的去练习。可以是对照着镜子练习，也可以是对着自己朋友练习，也可以找人模拟面试。熟能生巧，一定能够做到收放自如的。</p><h1 id="自我介绍例子" tabindex="-1">自我介绍例子 <a class="header-anchor" href="#自我介绍例子" aria-label="Permalink to &quot;自我介绍例子&quot;">​</a></h1><h2 id="面试官有时间听你bb版" tabindex="-1">面试官有时间听你bb版 <a class="header-anchor" href="#面试官有时间听你bb版" aria-label="Permalink to &quot;面试官有时间听你bb版&quot;">​</a></h2><p>我是顶真，来自斯川省礼堂县，毕业于斯川省礼堂大学，礼堂重点实验室，放牛专业。（基本信息）</p><p>在校期间我主要参与和攻克了雪豹养殖技术的相关技术的研究，该项目是我们实验室的自然科学基金项目，主要是为了解决在大自然条件下，雪豹养殖成活率不高的问题。（项目背景）</p><p>在这个项目中我主要负责了雪豹饲料模块的开发工作，传统的雪豹饲料采用的是自然野生动物作为饲料来进行雪豹养殖的。但是使用传统的雪豹养殖饲料，存在着雪豹发现饲料困难，雪豹可获取饲料少的问题。为了解决这个问题，我通过查阅大量文献资料，创新性的提出了采用人工饲料的方式进行雪豹的养殖工作。（项目内容）</p><p>通过我们提出的方法，雪豹的存活率提高了50%，雪豹的健壮程度提升了100%（项目成果）</p><p>另外了，我还参加了xxx项目、xxx实习（按照上面的项目背景+项目内容+项目成果三部曲来写）。</p><p>除了平时的研究工作之外呢，我在学校还非常喜欢打篮球、游泳等，身体素质比较好，相信以后能够胜任强度较高的工作。</p><h2 id="面试官没时间听你bb版-2分钟以内" tabindex="-1">面试官没时间听你bb版（2分钟以内） <a class="header-anchor" href="#面试官没时间听你bb版-2分钟以内" aria-label="Permalink to &quot;面试官没时间听你bb版（2分钟以内）&quot;">​</a></h2><p>我是顶真，来自斯川省礼堂县，毕业于斯川省礼堂大学，礼堂重点实验室，放牛专业。（基本信息）</p><p>在校期间我主要参与和攻克了雪豹养殖技术的相关技术的研究，该项目是我们实验室的自然科学基金项目，主要是为了解决在大自然条件下，雪豹养殖成活率不高的问题。（项目背景）在这个项目中呢，我们主要是通过我们提出的方法，将雪豹的存活率提高了50%，雪豹的健壮程度提升了100%（项目成果）</p><p>另外，还参加了xxx、xxx项目，这些项目发表的sci论文xxx篇，锻炼了实际项目能力。</p><p>除了平时的研究工作之外呢，我在学校还非常喜欢打篮球、游泳等，身体素质比较好，相信以后能够胜任强度较高的工作。</p>',56)])])}const b=p(x,[["render",o]]);export{c as __pageData,b as default};
